{"source":"import json
import sys
from datetime import datetime, timezone

def parse_iso8601(instant_str):
    """Parse an offset-aware ISO8601 string to a datetime with timezone."""
    if instant_str is None:
        return None
    # Handle 'Z' suffix by replacing with '+00:00'
    if instant_str.endswith('Z'):
        instant_str = instant_str[:-1] + '+00:00'
    # Parse with timezone info
    return datetime.fromisoformat(instant_str)

def main():
    input_file = sys.argv[1]
    with open(input_file, 'r') as f:
        data = json.load(f)

    as_of = parse_iso8601(data["as_of"])
    reminders = data.get("reminders", [])

    pending = []
    for r in reminders:
        # Skip completed reminders
        if r.get("completed", False):
            continue

        due_str = r.get("due")
        # Skip null, missing, or naive due values
        if due_str is None or due_str == "":
            continue

        due_dt = parse_iso8601(due_str)
        if due_dt is None:
            continue

        # Check if due AT OR BEFORE as_of
        if due_dt <= as_of:
            # Format due_utc as YYYY-MM-DDTHH:MM:SSZ
            due_utc = due_dt.strftime("%Y-%m-%dT%H:%M:%SZ")
            pending.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": due_utc
            })

    # Sort by actual due instant (we need to re-parse for sorting) then by id
    # We'll sort using the parsed datetime
    def sort_key(item):
        # Re-parse due_utc to get datetime for sorting
        dt = parse_iso8601(item["due_utc"].replace("Z", "+00:00"))
        return (dt, item["id"])

    pending.sort(key=sort_key)

    print(json.dumps(pending))

if __name__ == "__main__":
    main()"}

